\begin{aligned}
&\text{เนื่องจาก } (2+\sqrt{3})(2-\sqrt{3}) = 4 - 3 = 1 \\[4pt]
&\implies (2-\sqrt{3})^x = \frac{1}{(2+\sqrt{3})^x} \\[6pt]
&\text{ให้ } u = (2+\sqrt{3})^x \implies u + \frac{1}{u} = 4 \\[6pt]
&u^2 - 4u + 1 = 0 \implies u = \frac{4 \pm \sqrt{16-4}}{2} = 2 \pm \sqrt{3} \\[6pt]
&u = 2+\sqrt{3} \implies (2+\sqrt{3})^x = 2+\sqrt{3} \implies x = 1 \\[6pt]
&u = 2-\sqrt{3} \implies (2+\sqrt{3})^x = (2+\sqrt{3})^{-1} \implies x = -1 \\[6pt]
&\therefore \text{เซตคำตอบคือ } \{-1, 1\}
\end{aligned}

